return [{
  json: {
    verse: `Mind precedes all knowables,
mind's their chief, mind-made are they.
If with a corrupted mind
one should either speak or act
dukkha follows caused by that,
as does the wheel the ox's hoof.`,
    language: "English"
  }
}];

const raw = $json.output;

if (!raw) {
  throw new Error('AI Agent returned no output.');
}

let result;

if (typeof raw === 'object') {
  result = raw;
} else {
  const text = String(raw).trim();

  try {
    result = JSON.parse(text);
  } catch (firstError) {
    const cleaned = text
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    try {
      result = JSON.parse(cleaned);
    } catch (secondError) {
      throw new Error(
        'AI Agent did not return valid JSON. Raw output:\n' + text
      );
    }
  }
}

if (!result || typeof result !== 'object') {
  throw new Error('AI Agent output is not an object.');
}

if (typeof result.title !== 'string' || !result.title.trim()) {
  throw new Error('Missing or invalid title.');
}

if (typeof result.lyrics !== 'string' || !result.lyrics.trim()) {
  throw new Error('Missing or invalid lyrics.');
}

if (typeof result.image_prompt !== 'string' || !result.image_prompt.trim()) {
  throw new Error('Missing or invalid image_prompt.');
}

return [{
  json: {
    title: result.title.trim(),
    lyrics: result.lyrics.trim(),
    image_prompt: result.image_prompt.trim()
  }
}];

